import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"联合零售商店（Associated Retail Stores）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/联合零售商店.md","filePath":"03_companies/联合零售商店.md"}'),l={name:"03_companies/联合零售商店.md"};function o(d,a,h,n,s,c){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="联合零售商店-associated-retail-stores" tabindex="-1">联合零售商店（Associated Retail Stores） <a class="header-anchor" href="#联合零售商店-associated-retail-stores" aria-label="Permalink to &quot;联合零售商店（Associated Retail Stores）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>Associated Retail Stores / Diversified Retailing Company</td></tr><tr><td>行业</td><td>百货零售</td></tr><tr><td>CEO</td><td>本·罗斯纳（Ben Rosner）</td></tr><tr><td>收购主体</td><td>多元零售公司（Diversified Retailing Company）</td></tr><tr><td>收购时间</td><td>1966-1967年</td></tr><tr><td>伯克希尔持股</td><td>通过多元零售公司收购，后并入伯克希尔</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>百货零售连锁经营，在本·罗斯纳的经营管理下成为行业标杆型企业。</p><h2 id="收购故事" tabindex="-1">收购故事 <a class="header-anchor" href="#收购故事" aria-label="Permalink to &quot;收购故事&quot;">​</a></h2><h3 id="收购背景" tabindex="-1">收购背景 <a class="header-anchor" href="#收购背景" aria-label="Permalink to &quot;收购背景&quot;">​</a></h3><ul><li><strong>1966-1967年</strong>：巴菲特通过多元零售公司（Diversified Retailing Company）收购联合零售商店</li><li>多元零售公司是巴菲特早期收购的重要载体，后成为伯克希尔帝国的重要基石</li><li>收购完成后，多元零售公司与伯克希尔哈撒韦合并</li></ul><h3 id="收购逻辑" tabindex="-1">收购逻辑 <a class="header-anchor" href="#收购逻辑" aria-label="Permalink to &quot;收购逻辑&quot;">​</a></h3><ol><li><strong>管理型人才</strong>：本·罗斯纳是巴菲特极度欣赏的管理者典范</li><li><strong>成本控制</strong>：罗斯纳将成本控制做到极致，是零售业的标杆</li><li><strong>业务协同</strong>：与<a href="/03_companies/蓝筹印花.html">蓝筹印花</a>等业务形成协同效应</li><li><strong>长期价值</strong>：管理层优秀，能持续创造超额价值</li></ol><h2 id="核心管理层" tabindex="-1">核心管理层 <a class="header-anchor" href="#核心管理层" aria-label="Permalink to &quot;核心管理层&quot;">​</a></h2><h3 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>姓名</th><th>职位</th><th>特点</th></tr></thead><tbody><tr><td>本·罗斯纳（Ben Rosner）</td><td>CEO</td><td>成本控制大师，零售业管理典范</td></tr></tbody></table><h3 id="管理特点" tabindex="-1">管理特点 <a class="header-anchor" href="#管理特点" aria-label="Permalink to &quot;管理特点&quot;">​</a></h3><ul><li><strong>极致成本控制</strong>：罗斯纳以严苛的成本管理著称，是巴菲特心中理想管理者的代表</li><li><strong>高效运营</strong>：在零售行业微薄的利润率中创造超额回报</li><li><strong>长期任职</strong>：长期服务于公司，与巴菲特保持良好信任关系</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;本·罗斯纳是零售业最优秀的管理者之一，他将成本控制做到了极致。&quot; —— 巴菲特</p></blockquote><blockquote><p>&quot;我们寻找的不是会花公司钱的管理者，而是会替股东省钱的管理者。罗斯纳就是典范。&quot; —— 巴菲特</p></blockquote><h2 id="在伯克希尔体系中的位置" tabindex="-1">在伯克希尔体系中的位置 <a class="header-anchor" href="#在伯克希尔体系中的位置" aria-label="Permalink to &quot;在伯克希尔体系中的位置&quot;">​</a></h2><h3 id="多元化零售公司时期" tabindex="-1">多元化零售公司时期 <a class="header-anchor" href="#多元化零售公司时期" aria-label="Permalink to &quot;多元化零售公司时期&quot;">​</a></h3><ul><li>巴菲特通过<a href="/03_companies/蓝筹印花.html">蓝筹印花</a>控股多元零售公司</li><li>联合零售商店是多元零售公司的核心资产</li><li>罗斯纳作为核心管理者，负责日常运营</li></ul><h3 id="与伯克希尔合并" tabindex="-1">与伯克希尔合并 <a class="header-anchor" href="#与伯克希尔合并" aria-label="Permalink to &quot;与伯克希尔合并&quot;">​</a></h3><ul><li>多元零售公司后来与<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>合并</li><li>联合零售商店成为伯克希尔零售版图的重要组成部分</li><li>巴菲特通过这一模式实现了&quot;保险+零售&quot;的双轮驱动</li></ul><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 母公司</li><li><a href="/04_people/本·罗斯纳.html">本·罗斯纳</a> - 核心管理者</li><li><a href="/03_companies/蓝筹印花.html">蓝筹印花</a> - 收购主体公司</li></ul><hr><p><em>最后更新：2026-04-12</em></p>',27)])])}const m=t(l,[["render",o]]);export{b as __pageData,m as default};
